function playbackLength(ms){const s=Math.max(1,Math.round(ms/1000));if(s<60)return `${s}s`;if(s<3600)return `${Math.floor(s/60)}m ${String(s%60).padStart(2,'0')}s`;return `${Math.floor(s/3600)}h ${String(Math.round(s%3600/60)).padStart(2,'0')}m`;}
function updateRateLabel(){const i=PLAYBACK_RATES.indexOf(playbackRate);$('rateValue').textContent=`${playbackRate}×`;$('rateTotal').textContent=flight?`· full flight in ${playbackLength(flight.ms/playbackRate)}`:'';$('slower').disabled=i<=0;$('faster').disabled=i>=PLAYBACK_RATES.length-1;}
function setPlaybackRate(step){const i=Math.max(0,Math.min(PLAYBACK_RATES.length-1,PLAYBACK_RATES.indexOf(playbackRate)+step));playbackRate=PLAYBACK_RATES[i];try{localStorage.setItem('dayflight-rate',String(playbackRate));}catch{}updateRateLabel();}
function pause(){playing=false;$('play').textContent='▶';$('play').setAttribute('aria-label','Play flight simulation');}
function tick(now){if(playing&&flight){progress=Math.min(1,progress+(now-lastFrame)*playbackRate/flight.ms);if(progress>=1)pause();update();}lastFrame=now;requestAnimationFrame(tick);}
function toast(msg){$('toast').textContent=msg;$('toast').style.opacity=1;setTimeout(()=>$('toast').style.opacity=0,3000);}
function formState(){return {from:$('from').value,to:$('to').value,date:$('date').value,time:$('time').value,duration:$('duration').value,mode:$('timingMode').value,clockPrefs:{from:clockPreference('from'),to:clockPreference('to')},speedUnit,custom:custom?{...custom,tz:$('toPointZone').value||custom.tz}:null,customFrom:customFrom?{...customFrom,tz:$('fromPointZone').value||customFrom.tz}:null};}
