function restoreForm(s){for(const key of ['from','to','date','time','duration'])if(s[key])$(key).value=s[key];$('timingMode').value=s.mode||'duration';speedUnit=Object.hasOwn(SPEED_FACTORS,s.speedUnit)?s.speedUnit:'knots';setMode();custom=s.custom||null;customFrom=s.customFrom||null;for(const id of ['from','to']){const point=locationPoint(id);if(point){point.kind=point.kind||'map';point.city=point.kind==='map'?'Map point':'Coordinates';point.inputValue=point.inputValue||`${point.lat.toFixed(6)}, ${point.lon.toFixed(6)}`;$(id).value=point.inputValue;setPointZone(id,point);}}setDepartureTime($('time').value);updateDateButton();applyClockPreference('from',s.clockPrefs?.from||{mode:s.offsetMode||'auto',offset:s.utcOffset||''});applyClockPreference('to',s.clockPrefs?.to||{mode:'auto',offset:''});updateNotes();}
async function init(){try{[airports,land]=await Promise.all([fetch('airports.json').then(r=>{if(!r.ok)throw Error();return r.json();}),fetch('land.json').then(r=>{if(!r.ok)throw Error();return r.json();})]);const zones=['UTC',...Intl.supportedValuesOf('timeZone')];for(const id of ['from','to'])$(id+'PointZone').replaceChildren(...zones.map(z=>Object.assign(document.createElement('option'),{value:z,textContent:z.replaceAll('_',' ')})));$('from').value='YSSY';$('to').value='EGLL';$('date').value=new Date().toLocaleDateString('en-CA',{timeZone:'Australia/Sydney'});setDepartureTime('16:00');updateDateButton();$('duration').value='23.5';setMode();let state;try{state=location.hash?JSON.parse(decodeURIComponent(location.hash.slice(1))):JSON.parse(localStorage.getItem('dayflight'));}catch{}if(state){try{restore(state);}catch(err){toast('Saved plan could not be restored: '+err.message);}}initSimbriefUI();calculate();}catch(err){$('error').textContent='Could not load map or airports. Reload to try again.';console.error(err);}}
// UI bindings

for(const [listId,fieldId,count]of [['hourOptions','departureHour',24],['minuteOptions','departureMinute',60]]){const list=$(listId);for(let value=0;value<count;value++){const button=document.createElement('button');button.type='button';button.role='option';button.dataset.value=String(value).padStart(2,'0');button.textContent=button.dataset.value;button.setAttribute('aria-label',`${button.dataset.value} ${fieldId==='departureHour'?'hours':'minutes'}`);button.onclick=()=>{$(fieldId).value=button.dataset.value;syncDepartureTime();};list.append(button);}list.onkeydown=e=>{if(['ArrowUp','ArrowDown','Home','End','PageUp','PageDown'].includes(e.key)){e.preventDefault();let value=Number($(fieldId).value);if(e.key==='Home')value=0;else if(e.key==='End')value=count-1;else value+=e.key==='ArrowUp'?-1:e.key==='ArrowDown'?1:e.key==='PageUp'?-5:5;$(fieldId).value=String(boundedTimeValue(value,count-1)).padStart(2,'0');syncDepartureTime();const selected=list.querySelector('[aria-selected="true"]');selected.focus({preventScroll:true});selected.scrollIntoView({block:'nearest'});}else if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();$(listId==='hourOptions'?'minuteOptions':'hourOptions').querySelector('[aria-selected="true"]')?.focus({preventScroll:true});}};}
